// Repository guards (plan 3.5, 7.1, K13, K21, K25). Owned by nobody in Step 2: report a failure
// caused by another workstream's file, do not edit this file.
import assert from 'node:assert/strict'
import { readFileSync, readdirSync, statSync } from 'node:fs'
import path from 'node:path'
import { test } from 'node:test'

const ROOT = process.cwd()
const SRC = path.join(ROOT, 'src')
// The Step 1 parking folder src/components/legacy was deleted in Step 3; no exclusion remains.
const LEGACY_PARKING: string | null = null

const rel = (file: string) => path.relative(ROOT, file).split(path.sep).join('/')

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const full = path.join(dir, name)
    return statSync(full).isDirectory() ? walk(full) : [full]
  })
}

const srcFiles = walk(SRC)
const isText = (file: string) => /\.(ts|tsx|mts|js|jsx|mjs|cjs|css|scss|json|svg|md|txt|sql)$/.test(file)
const inLegacyParking = (file: string) => LEGACY_PARKING !== null && rel(file).startsWith(LEGACY_PARKING)
const read = (file: string) => readFileSync(file, 'utf8')

// Assembled from parts so that this file can live anywhere without tripping its own check.
const LEGACY_NAMES = [['crew', 'members'], ['ship', 'subsystems'], ['ship', 'records']].map((p) => p.join('_'))
const LEGACY_NAME_PATTERN = new RegExp(LEGACY_NAMES.join('|'))
const LEGACY_IDENTIFIER_PATTERN = new RegExp(
  `(from|join|into|update|table)\\s+("?public"?\\.)?"?(${LEGACY_NAMES.join('|')})`, 'i')
const LEGACY_KEYS_FILE = 'src/lib/data/legacy-keys.ts'

test('package.json has no script that could reach the live schema (push, pull, introspect, studio)', () => {
  const pkg = JSON.parse(read(path.join(ROOT, 'package.json'))) as { scripts: Record<string, string> }
  for (const [name, command] of Object.entries(pkg.scripts)) {
    assert.doesNotMatch(`${name} ${command}`, /\b(push|pull|introspect|studio)\b/, `script "${name}"`)
  }
  assert.equal(pkg.scripts.build, 'next build', 'migrations never run in the build (K15)')
})

test('drizzle.config.ts holds no path to the database', () => {
  assert.doesNotMatch(read(path.join(ROOT, 'drizzle.config.ts')), /dbCredentials|DATABASE_URL/)
})

test('the legacy table names appear in src/ only in legacy-keys.ts', () => {
  const offenders = srcFiles
    .filter((file) => isText(file) && rel(file) !== LEGACY_KEYS_FILE && LEGACY_NAME_PATTERN.test(read(file)))
    .map(rel)
  assert.deepEqual(offenders, [])
  const keys = read(path.join(ROOT, LEGACY_KEYS_FILE))
  for (const name of LEGACY_NAMES) assert.ok(keys.includes(`'${name}'`), `${name} is defined in legacy-keys.ts`)
})

test('no file under src/ uses a legacy table name as an SQL identifier (legacy-keys.ts included)', () => {
  const offenders = srcFiles.filter((file) => isText(file) && LEGACY_IDENTIFIER_PATTERN.test(read(file))).map(rel)
  assert.deepEqual(offenders, [])
})

test('the schema file does not describe a legacy table', () => {
  assert.doesNotMatch(read(path.join(SRC, 'lib', 'db', 'schema.ts')), LEGACY_NAME_PATTERN)
})

test('no dangerouslySetInnerHTML anywhere in src/ (K21)', () => {
  const offenders = srcFiles.filter((file) => /\.(ts|tsx)$/.test(file) && read(file).includes('dangerouslySetInnerHTML')).map(rel)
  assert.deepEqual(offenders, [])
})

test('src/ contains no .js, .jsx or .css file', () => {
  const offenders = srcFiles.filter((file) => /\.(js|jsx|css)$/.test(file) && !inLegacyParking(file)).map(rel)
  assert.deepEqual(offenders, [])
})

test('@media appears only in src/styles/ and globals.scss, never in a module (K25)', () => {
  const offenders = srcFiles
    .filter((file) => file.endsWith('.scss') && !inLegacyParking(file))
    .filter((file) => !rel(file).startsWith('src/styles/') && rel(file) !== 'src/app/globals.scss')
    .filter((file) => /@media\b/.test(read(file)))
    .map(rel)
  assert.deepEqual(offenders, [])
})

test('the Sass partials in src/styles/ produce no CSS: only @use, @forward, variables, mixins and functions at top level', () => {
  for (const file of walk(path.join(SRC, 'styles'))) {
    const text = read(file).replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/[^\n]*/g, '')
    let depth = 0
    let statement = ''
    for (const char of text) {
      if (char === '{') {
        if (depth === 0) {
          assert.match(statement.trim(), /^@(mixin|function)\b/, `${rel(file)}: top-level block "${statement.trim().slice(0, 40)}"`)
          statement = ''
        }
        depth += 1
      } else if (char === '}') {
        depth -= 1
      } else if (depth === 0) {
        if (char === ';') {
          assert.match(statement.trim(), /^(@use|@forward|\$[\w-]+\s*:)/, `${rel(file)}: top-level statement "${statement.trim().slice(0, 40)}"`)
          statement = ''
        } else {
          statement += char
        }
      }
    }
  }
})

test('nothing in the parked legacy folder imports from src/app', () => {
  if (LEGACY_PARKING === null) return
  const offenders = srcFiles
    .filter((file) => inLegacyParking(file) && /\.(ts|tsx)$/.test(file))
    .filter((file) => /from ['"](@\/app|(\.\.\/)+app)\//.test(read(file)))
    .map(rel)
  assert.deepEqual(offenders, [])
})

test('.gitignore keeps secrets and backups out of git and no longer ignores the lockfile', () => {
  const lines = read(path.join(ROOT, '.gitignore')).split(/\r?\n/)
  for (const expected of ['.env', '.env.*', '!.env.example', '/backups/', '/.secrets/']) {
    assert.ok(lines.includes(expected), `.gitignore has ${expected}`)
  }
  assert.ok(!lines.includes('package-lock.json'))
})
